import React from 'react';
import { Container, List, Title } from './styles'; // Importando os estilos do arquivo
import { Props } from '.';

const ProductsList: React.FC<Props> = ({ title, pratos, size = 'grande' }) => { // Definindo o valor default como 'grande'
  return (
    <Container>
      <div>
        <Title>{title}</Title>
        <List size={size}>
          {pratos.map((prato) => (
            <div key={prato.id}>
              {/* Renderizando os pratos */}
              <img src={prato.image} alt={prato.title} />
              <h3>{prato.title}</h3>
              <p>{prato.description}</p>
            </div>
          ))}
        </List>
      </div>
    </Container>
  )
}

export default ProductsList;
